-- Three distinct operating layers; original employment and posted finance stay intact.
ALTER TABLE ty_ledger ADD COLUMN parent_ledger_id bigint REFERENCES ty_ledger(id);
ALTER TABLE ty_company ADD COLUMN parent_company_id bigint REFERENCES ty_company(id);
ALTER TABLE ty_company ADD COLUMN org_level text CHECK(org_level IN('group','brand','store'));
ALTER TABLE ty_company_position ADD COLUMN parent_position_id bigint REFERENCES ty_company_position(id);
CREATE FUNCTION fn_ty_hierarchy_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE p public.ty_company%ROWTYPE; l public.ty_ledger%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='ty_ledger' THEN
  IF NEW.parent_ledger_id IS NOT NULL THEN
   SELECT * INTO l FROM public.ty_ledger WHERE id=NEW.parent_ledger_id;
   IF l.group_id<>NEW.group_id OR l.scope_mode<>'group' OR l.parent_ledger_id IS NOT NULL OR l.id=NEW.id THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='品牌子帐须归属同集团的根集团帐'; END IF;
  END IF; RETURN NEW;
 END IF;
 IF NEW.org_level IN('brand','store') AND NEW.parent_company_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='品牌公司与门店须选择上级组织'; END IF;
 IF NEW.org_level='group' AND NEW.parent_company_id IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='集团节点不能再挂上级公司'; END IF;
 IF NEW.parent_company_id IS NOT NULL THEN
  SELECT * INTO p FROM public.ty_company WHERE id=NEW.parent_company_id FOR SHARE;
  IF p.group_id<>NEW.group_id OR p.id=NEW.id OR NOT((NEW.org_level='brand' AND p.org_level='group') OR(NEW.org_level='store' AND p.org_level='brand' AND NEW.brand_id=p.brand_id)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='公司层级必须是同集团的集团—品牌公司—门店，门店品牌须与上级一致'; END IF;
 ELSIF NEW.org_level IN('brand','store') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='品牌公司和门店须明确上级组织'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ty_hierarchy_company BEFORE INSERT OR UPDATE ON ty_company FOR EACH ROW EXECUTE FUNCTION fn_ty_hierarchy_guard();
CREATE TRIGGER ty_hierarchy_ledger BEFORE INSERT OR UPDATE ON ty_ledger FOR EACH ROW EXECUTE FUNCTION fn_ty_hierarchy_guard();
CREATE FUNCTION fn_ty_position_inheritance_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE p public.ty_company_position%ROWTYPE; c public.ty_company%ROWTYPE;
BEGIN
 IF NEW.parent_position_id IS NOT NULL THEN
  SELECT * INTO p FROM public.ty_company_position WHERE id=NEW.parent_position_id;
  SELECT * INTO c FROM public.ty_company WHERE id=NEW.company_id;
  IF p.group_id<>NEW.group_id OR p.job_id<>NEW.job_id OR p.company_id IS DISTINCT FROM c.parent_company_id OR p.id=NEW.id THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='下级岗位须承接直属上级组织的同一标准岗位'; END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER ty_position_inheritance BEFORE INSERT OR UPDATE ON ty_company_position FOR EACH ROW EXECUTE FUNCTION fn_ty_position_inheritance_guard();
CREATE TABLE ty_headcount_plan(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 department_id bigint REFERENCES ty_department(id),position_id bigint REFERENCES ty_company_position(id),
 period date NOT NULL CHECK(extract(day FROM period)=1),quota integer NOT NULL CHECK(quota>=0),
 reason text NOT NULL CHECK(length(btrim(reason))>=4),updated_by bigint NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(position_id IS NULL OR department_id IS NOT NULL)
);
CREATE UNIQUE INDEX ty_headcount_plan_once ON ty_headcount_plan(company_id,period,coalesce(department_id,0),coalesce(position_id,0));
CREATE FUNCTION fn_ty_headcount_plan_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$
DECLARE parent_co bigint; parent_dept bigint; parent_pos bigint; cap integer; total integer;
BEGIN
 PERFORM pg_advisory_xact_lock(NEW.group_id::integer,(extract(year FROM NEW.period)::integer*100+extract(month FROM NEW.period)::integer));
 IF NOT EXISTS(SELECT 1 FROM public.ty_company WHERE id=NEW.company_id AND group_id=NEW.group_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='编制所属集团公司不一致'; END IF;
 IF NEW.department_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_department WHERE id=NEW.department_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='编制部门不属于本公司'; END IF;
 IF NEW.position_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company_position WHERE id=NEW.position_id AND company_id=NEW.company_id AND department_id=NEW.department_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='岗位编制须对应本部门的岗位设置'; END IF;
 parent_co:=NEW.company_id;
 IF NEW.position_id IS NOT NULL THEN parent_dept:=NEW.department_id;
 ELSIF NEW.department_id IS NOT NULL THEN SELECT parent_department_id INTO parent_dept FROM public.ty_department WHERE id=NEW.department_id;
 ELSE SELECT parent_company_id INTO parent_co FROM public.ty_company WHERE id=NEW.company_id;
 END IF;
 IF parent_co IS NOT NULL THEN
  SELECT quota INTO cap FROM public.ty_headcount_plan WHERE company_id=parent_co AND department_id IS NOT DISTINCT FROM parent_dept AND position_id IS NULL AND period=NEW.period;
  IF cap IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='请先核定同月上级组织或部门编制'; END IF;
  IF NEW.position_id IS NOT NULL THEN
   SELECT coalesce(sum(quota),0) INTO total FROM public.ty_headcount_plan WHERE company_id=NEW.company_id AND department_id=NEW.department_id AND position_id IS NOT NULL AND period=NEW.period AND id<>NEW.id;
  ELSIF NEW.department_id IS NOT NULL THEN
   SELECT coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h JOIN public.ty_department d ON d.id=h.department_id WHERE h.company_id=NEW.company_id AND h.position_id IS NULL AND d.parent_department_id IS NOT DISTINCT FROM parent_dept AND h.period=NEW.period AND h.id<>NEW.id;
   IF parent_dept IS NULL THEN SELECT total+coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h JOIN public.ty_company c ON c.id=h.company_id WHERE c.parent_company_id=NEW.company_id AND h.department_id IS NULL AND h.period=NEW.period; END IF;
  ELSE
   SELECT coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h JOIN public.ty_company c ON c.id=h.company_id WHERE c.parent_company_id=parent_co AND h.department_id IS NULL AND h.period=NEW.period AND h.id<>NEW.id;
   SELECT total+coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h JOIN public.ty_department d ON d.id=h.department_id WHERE h.company_id=parent_co AND d.parent_department_id IS NULL AND h.position_id IS NULL AND h.period=NEW.period;
  END IF;
  IF total+NEW.quota>cap THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='下级编制分配合计超过上级核定额度'; END IF;
 END IF;
 -- A parent reduction cannot strand its existing children above the new cap.
 IF NEW.position_id IS NULL THEN
  IF NEW.department_id IS NULL THEN
   SELECT coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h JOIN public.ty_company c ON c.id=h.company_id WHERE c.parent_company_id=NEW.company_id AND h.department_id IS NULL AND h.period=NEW.period;
   SELECT total+coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h JOIN public.ty_department d ON d.id=h.department_id WHERE h.company_id=NEW.company_id AND d.parent_department_id IS NULL AND h.position_id IS NULL AND h.period=NEW.period;
  ELSE
   SELECT coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h WHERE h.company_id=NEW.company_id AND h.department_id=NEW.department_id AND h.position_id IS NOT NULL AND h.period=NEW.period;
   SELECT total+coalesce(sum(h.quota),0) INTO total FROM public.ty_headcount_plan h JOIN public.ty_department d ON d.id=h.department_id WHERE d.parent_department_id=NEW.department_id AND h.position_id IS NULL AND h.period=NEW.period;
  END IF;
  IF total>NEW.quota THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='已分配下级额度超过本次核定，须先调整下级'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER ty_headcount_plan_guard BEFORE INSERT OR UPDATE ON ty_headcount_plan FOR EACH ROW EXECUTE FUNCTION fn_ty_headcount_plan_guard();
DO $$ DECLARE c record; BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='ty_test_account_profile'::regclass AND contype='c' AND (pg_get_constraintdef(oid) LIKE '%profile_code%' OR pg_get_constraintdef(oid) LIKE '%company_id%') LOOP EXECUTE format('ALTER TABLE ty_test_account_profile DROP CONSTRAINT %I',c.conname); END LOOP; END $$;
ALTER TABLE ty_test_account_profile ADD CHECK(profile_code IN('config_admin','demo','boss','hr_manager','recruiter','payroll','trainer','hr_staff','store_manager','store_staff','station_staff','group_hr_director','company_hr_director'));
ALTER TABLE ty_test_account_profile ADD CHECK(person_id IS NULL OR company_id IS NOT NULL);
INSERT INTO sys_role(id,code,name,description) SELECT coalesce(max(id),1000)+1,'ty_group_hr_director','集团HR总监','集团范围全部HR与组织授权' FROM sys_role;
INSERT INTO sys_role(id,code,name,description) SELECT max(id)+1,'ty_company_hr_director','公司HR总监','本公司及下属公司全部HR业务，不跨公司授权' FROM sys_role;
INSERT INTO sys_role_resource(role_id,resource_code,can_read,can_write) SELECT r.id,s.resource_code,true,(r.code='ty_group_hr_director' OR s.resource_code NOT IN('ledger','integration')) FROM sys_role r CROSS JOIN sys_perm_resource s WHERE r.code IN('ty_group_hr_director','ty_company_hr_director');
INSERT INTO sys_check_registry(check_code,name,domain,kind,guard_object,guard_schema,guard_table,guard_kind,runner,assertion_sql) VALUES('TYHR.THREE-LEVEL','三层组织与编制','ORG','ACL','ty_headcount_plan_guard','public','ty_headcount_plan','TRIGGER','node test/advanced-time.test.mjs','node test/advanced-time.test.mjs');
